import { buildStreamUrl, getStreamsUrl } from '@netscript/plugin-streams-core';
import { bindStreamEventSourceV1 } from '@netscript/fresh/streams';

// Native EventSource needs the real stream route, an opaque replay offset, and
// live=sse. It cannot attach arbitrary authorization headers, so use this from
// a same-origin/cookie-compatible route or proxy when the service is protected.
const url = new URL(buildStreamUrl('/workers/executions', getStreamsUrl()));
url.searchParams.set('offset', '-1');
url.searchParams.set('live', 'sse');
const source = new EventSource(url);

const latest = new Map<string, unknown>();
const binding = bindStreamEventSourceV1({
  source,
  onEvent(event) {
    // The helper registers named data/control listeners and validates both
    // payload schemas before delivering this exhaustive outcome union.
    if (event.event === 'error') { latest.set('$error', event.payload); return; }
    if (event.event !== 'data') return; // control / derived heartbeat
    for (const change of event.payload) { // data is always an ordered array
      if (change.headers.operation === 'delete') latest.delete(change.key);
      else latest.set(change.key, change.value);
    }
  },
});

// An island should call binding.dispose() from its effect cleanup. This plain
// browser example closes on page teardown; W3-A owns reconnect policy.
addEventListener('pagehide', () => binding.dispose(), { once: true });"
